const byId=Object.fromEntries(chords.map(c=>[c.id,c]));
const strummingChordIds=course=>chords.filter(chord=>chord.menu!==false&&(!chord.variantOf||chord.relation==='chord-variation')&&(course==='guitar'?!chord.strings:course.startsWith('bar-')?chord.id.startsWith('bar-'):chord.id.startsWith('uke-'))).map(chord=>chord.id);
const chordSelectOptions=(ids,selected)=>{const recommended=ids.filter(id=>!byId[id].variantOf),variations=ids.filter(id=>byId[id].relation==='chord-variation'),options=list=>list.map(id=>`<option value="${id}"${id===selected?' selected':''}>${byId[id].measureName||byId[id].name}</option>`).join('');return `<optgroup label="Recommended chords">${options(recommended)}</optgroup>${variations.length?`<optgroup label="Chord variations">${options(variations)}</optgroup>`:''}`;};
const guitarStrings=['E','A','D','G','B','e'];
const counts=['1','&','2','&','3','&','4','&'];
const threeFourCounts=['1','&','2','&','3','&'];
const sixteenthCounts=['1','e','&','a','2','e','&','a','3','e','&','a','4','e','&','a'];
const strokeCells=(pattern,labels=counts)=>[...pattern.padEnd(labels.length,'.').slice(0,labels.length)].map((s,i)=>`<i class="${s==='d'?'down':s==='u'?'up':'rest'}" title="${s==='d'?'Down':s==='u'?'Up':'No strum'} on ${labels[i]}">${s==='d'?'↓':s==='u'?'↑':'·'}</i>`).join('');
const rhythmMarkup=(pattern,subdivision,meter=4)=>{const labels=subdivision==='sixteenth'?sixteenthCounts:meter===3?threeFourCounts:counts;return `<div class="measure-grid count-row${subdivision==='sixteenth'?' sixteenth-count':''}" style="--rhythm-slots:${labels.length}">${labels.map(x=>`<b>${x}</b>`).join('')}</div><div class="measure-grid stroke-row${subdivision==='sixteenth'?' sixteenth-strokes':''}" style="--rhythm-slots:${labels.length}">${strokeCells(pattern,labels)}</div>`;};

function diagram(chord){
 const stringSet=chord.strings||guitarStrings,count=stringSet.length,top=count===4?31:24,step=count===4?27:19,bottom=top+(count-1)*step,nutTop=top-7,nutHeight=bottom-top+14;
 const rows=[...stringSet].reverse().map((label,index)=>{const si=count-1-index,y=top+index*step,fret=chord.frets[si],finger=chord.fingers[si],muted=fret==='x',weight=(1.15+index*(count===4?.5:.38)).toFixed(2);let marker='';
  if(muted)marker=`<text x="48" y="${y+5}" class="mute">×</text>`;
  else if(fret===0)marker=`<circle cx="48" cy="${y}" r="6" class="open"/>`;
  else if(!(chord.bar&&fret===chord.bar.fret&&si>=chord.bar.from&&si<=chord.bar.to)){const x=70+(fret-.5)*58,anchor=chord.anchors.includes(si)?' anchor':'';marker=`<circle cx="${x}" cy="${y}" r="8.5" class="finger${anchor}"/><text x="${x}" y="${y+4}" class="finger-number">${finger}</text>`;}
  return `<text x="25" y="${y+5}" class="string-name${muted?' muted-label':''}">${label}</text><line x1="58" y1="${y+1.6}" x2="303" y2="${y+1.6}" class="string-shadow${muted?' muted-string-shadow':''}" style="stroke-width:${(Number(weight)+1.1).toFixed(2)}"/><line x1="58" y1="${y}" x2="303" y2="${y}" class="string-line${muted?' muted-string':''}" style="stroke-width:${weight}"/>${marker}`;
 }).join('');
 const frets=[126,185,244,303].map(x=>`<line x1="${x}" y1="${top}" x2="${x}" y2="${bottom}" class="fret"/>`).join('');
 let barre='';if(chord.bar){const x=70+(chord.bar.fret-.5)*58,y1=top+(count-1-chord.bar.to)*step,y2=top+(count-1-chord.bar.from)*step,mid=(y1+y2)/2;barre=`<rect x="${x-8.5}" y="${y1-8.5}" width="17" height="${y2-y1+17}" rx="8.5" class="barre"/><text x="${x}" y="${mid+4}" class="finger-number barre-number">1</text>`;}
 return `<svg class="chord-diagram" viewBox="0 0 315 136" role="img" aria-label="${chord.name} chord diagram for ${stringSet.join(' ')} tuning"><rect x="74" y="${nutTop}" width="229" height="${nutHeight}" rx="2" class="fretboard"/><rect x="59" y="${nutTop}" width="16" height="${nutHeight}" rx="1.5" class="nut"/>${frets}${rows}${barre}</svg>`;
}
function variationLinks(c){return c.variants?.length?`<div class="variation-links"><span>ALTERNATES & VARIATIONS</span>${c.variants.map(id=>`<button data-preview-chord="${id}">${byId[id].name}</button>`).join('')}</div>`:'';}
const playIcon=()=>'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path class="play-fill" d="m10 8 6 4-6 4V8Z"/></svg>';
const speakerIcon=()=>'<svg viewBox="0 0 75 75" aria-hidden="true"><path d="M39.389 13.769 22.235 28.606H6v19.093h15.989L39.389 62.75V13.769Z"/><path d="M48 27.6a19.5 19.5 0 0 1 0 21.4M55.1 20.5a30 30 0 0 1 0 35.6M61.6 14a38.8 38.8 0 0 1 0 48.6"/></svg>';
function chordCard(c){const kind=c.variantOf?(c.relation==='chord-variation'?'CHORD VARIATION':'ALTERNATE SHAPE'):'RECOMMENDED SHAPE';return `<article class="chord-card" data-chord-card="${c.id}"><div class="chord-card-heading"><div><span>${kind}</span><h2>${c.name}</h2></div><button type="button" class="play-chord" data-play-chord="${c.id}" aria-label="Hear ${c.name} chord">${speakerIcon()}</button></div>${diagram(c)}${variationLinks(c)}</article>`;}
const cards=ids=>ids.map(id=>chordCard(byId[id])).join('');
const chordButton=id=>`<button class="preview-chord" data-preview-chord="${id}" aria-label="Show ${byId[id].name} chord">${byId[id].measureName||byId[id].name}</button>`;
function measure(id,pattern='d.d.d.d.',subdivision='eighth',meter=4){
 return `<div class="music-measure"><div class="measure-heading">${chordButton(id)}</div>${rhythmMarkup(pattern,subdivision,meter)}</div>`;
}
function beatMeasure(ids,pattern,subdivision='eighth'){
 const paired=ids.length===4&&ids[0]===ids[1]&&ids[2]===ids[3];
 const labels=paired?[ids[0],ids[2]]:ids;
 return `<div class="music-measure beat-chord-measure${paired?' paired-chords':''}"><div class="measure-heading beat-chord-grid">${labels.map(id=>chordButton(id)).join('')}</div>${rhythmMarkup(pattern,subdivision)}</div>`;
}
function exercise(number,progression,copy,{primary=true,pattern='d.d.d.d.',repeat='REPEAT',bpm=84,groove='click',subdivision='eighth',meter=4,title='',keyOptions=[]}={}){const drumToggle='<button type="button" class="groove-toggle" aria-label="Turn drum backing on" aria-pressed="false"><strong>Drums</strong><span class="groove-switch" aria-hidden="true"></span></button>';return `<article class="change-card ${primary?'essential':'extra'}" data-exercise-number="${number}" data-exercise-title="${title}"${keyOptions.length?` data-key-options='${JSON.stringify(keyOptions)}'`:''} data-audio-progression='${JSON.stringify(progression)}' data-audio-pattern="${pattern}" data-audio-bpm="${bpm}" data-audio-groove="${groove}" data-audio-subdivision="${subdivision}" data-audio-meter="${meter}" data-drums-enabled="false"><div class="change-top"><div class="change-number">${number}</div><p class="change-label">${primary?'ESSENTIAL PRACTICE':'EXTRA PRACTICE'}</p><em>${repeat}</em></div><div class="exercise-toolbar"><button type="button" class="play-exercise" aria-label="Follow exercise ${number}" aria-pressed="false">${playIcon()}<span>Follow Along</span></button>${drumToggle}<div class="exercise-tempo" aria-label="Example tempo"><button type="button" class="tempo-step" data-tempo-step="-4" aria-label="Decrease tempo">−</button><label><input class="exercise-tempo-value" type="number" inputmode="numeric" min="40" max="200" step="1" value="${bpm}" aria-label="Custom tempo"><span>BPM</span></label><button type="button" class="tempo-step" data-tempo-step="4" aria-label="Increase tempo">+</button></div></div><div class="measure-row${progression.some(Array.isArray)?' has-split-measure':''}${progression.length>4?' long-progression':''}" style="--bar-count:${progression.length}">${progression.map((id,index)=>{const slotsPerMeasure=(subdivision==='sixteenth'?4:2)*meter,barIndex=index%Math.max(1,Math.ceil(pattern.length/slotsPerMeasure)),barPattern=pattern.slice(barIndex*slotsPerMeasure,barIndex*slotsPerMeasure+slotsPerMeasure);return Array.isArray(id)?beatMeasure(id,barPattern,subdivision):measure(id,barPattern,subdivision,meter);}).join('')}</div><p class="exercise-copy">${copy}</p></article>`;}
function applyExercisePattern(card,pattern,subdivision='eighth',meter=4){const slotsPerMeasure=(subdivision==='sixteenth'?4:2)*meter,bars=Math.max(1,Math.ceil(pattern.length/slotsPerMeasure));card.dataset.audioPattern=pattern;card.dataset.audioSubdivision=subdivision;card.dataset.audioMeter=String(meter);card.querySelectorAll('.music-measure').forEach((measure,index)=>{const barPattern=pattern.slice((index%bars)*slotsPerMeasure,(index%bars+1)*slotsPerMeasure);measure.querySelectorAll('.count-row,.stroke-row').forEach(row=>row.remove());measure.insertAdjacentHTML('beforeend',rhythmMarkup(barPattern,subdivision,meter));});}
function applyExerciseProgression(card,progression){const pattern=card.dataset.audioPattern||'d.d.d.d.',subdivision=card.dataset.audioSubdivision||'eighth',meter=Number(card.dataset.audioMeter||4),slotsPerMeasure=(subdivision==='sixteenth'?4:2)*meter,bars=Math.max(1,Math.ceil(pattern.length/slotsPerMeasure)),row=card.querySelector('.measure-row');card.dataset.audioProgression=JSON.stringify(progression);row.classList.toggle('has-split-measure',progression.some(Array.isArray));row.classList.toggle('long-progression',progression.length>4);row.style.setProperty('--bar-count',progression.length);row.innerHTML=progression.map((id,index)=>{const barPattern=pattern.slice((index%bars)*slotsPerMeasure,(index%bars+1)*slotsPerMeasure);return Array.isArray(id)?beatMeasure(id,barPattern,subdivision):measure(id,barPattern,subdivision,meter);}).join('');}
const objectiveOneVisuals=()=>`<section class="objective-one-visuals" aria-label="Objective 1 visual guides"><p>VISUAL GUIDES · TAP TO ENLARGE</p><div><button type="button" data-objective-image="./images/objective-one/fretboard-and-down-strum.png" data-objective-caption="The fretting area and the direction of a down-strum."><img src="./images/objective-one/fretboard-and-down-strum.png" alt="Instrument fretboard and down-strum direction guide"></button><button type="button" data-objective-image="./images/objective-one/strum-directions.png" data-objective-caption="Down-strums travel toward the floor; up-strums return toward the ceiling."><img src="./images/objective-one/strum-directions.png" alt="Down-strum and up-strum direction guide"></button></div></section>`;
const objectiveOneCallout=(title,items)=>`<aside class="strum-callout"><div class="callout-mark">↓</div><div><p>OBJECTIVE NOTES</p><h3>${title}</h3><ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul>${objectiveOneVisuals()}</div></aside>`;
const objectiveOneReturn=()=>`<li class="objective-one-return"><strong>Need the foundation again?</strong> <button type="button" data-return-objective-one>Review Objective 1</button> for string names, fret numbers, finger numbers, open and muted strings, and basic strumming direction.</li>`;
function techniqueCallout(type){
 if(type==='guitar-one')return objectiveOneCallout('Build the key-of-G foundation and connect the beat.', ['<strong>Use the anchor finger:</strong> Keep finger 3 planted through G, Cadd9, and D; release it for Em.','<strong>Skip the pick for now.</strong> Chord shapes and strumming first - pick later.','<strong>Connect the beat:</strong> Lightly rake down with the index fingernail. Count <strong>1 · 2 · 3 · 4</strong>; the strum and tapping foot go down together.']);
 if(type==='bar-one')return objectiveOneCallout('Learn the baritone ukulele map and connect the beat.', ['Build each shape with the same lead finger every time. G and Em begin with one finger; use those easy shapes to learn how the hand moves.','Strum all four strings with a relaxed index finger. Count <strong>1 · 2 · 3 · 4</strong>; the strum and tapping foot go down together.','The visual examples use a guitar, but the fret, finger, and strumming directions work the same way on baritone ukulele.']);
 if(type==='uke-one')return objectiveOneCallout('Learn the standard ukulele map and connect the beat.', ['Build each shape with the same lead finger every time. C and Am begin with one finger; use those easy shapes to learn how the hand moves.','Strum all four strings with a relaxed index finger. Count <strong>1 · 2 · 3 · 4</strong>; the strum and tapping foot go down together.','The visual examples use a guitar, but the fret, finger, and strumming directions work the same way on standard ukulele.']);
 if(type==='guitar-two')return `<aside class="strum-callout"><div class="callout-mark">↑</div><div><p>OBJECTIVE NOTES</p><h3>Move beyond one key and unlock more songs.</h3><ul><li>The key of G can only take us so far. C and Am introduce crucial shapes from C major; Am also belongs to the key of G. E gives us another common major shape and leads naturally into Am.</li><li>Use one lead finger instead of moving the whole hand at once; place that finger first, then build the rest of the chord.</li><li>Keep the downbeats on <strong>1 · 2 · 3 · 4</strong>. On the final <strong>&</strong>, lightly brush upward across the highest three or four strings with the side of your thumb.</li>${objectiveOneReturn()}</ul></div></aside>`;
 if(type==='guitar-three')return `<aside class="strum-callout"><div class="callout-mark">↕</div><div><p>OBJECTIVE NOTES</p><h3>Complete the core families and combine the rhythms.</h3><ul><li>A, Dm, F, Bm, and B7 add useful pieces from the keys of C, A, G, E, and D. These five key families form the beginning of the CAGED system used across the guitar neck.</li><li>Start with the F-Alternative. Bm, barred A, and full F introduce the hand position used for barre chords.</li><li>This objective mixes the strumming learned so far. Use four steady down-strums whenever a new pattern is not comfortable yet.</li>${objectiveOneReturn()}</ul></div></aside>`;
 if(type==='uke-young')return `<aside class="strum-callout"><div class="callout-mark">↓</div><div><p>OBJECTIVE NOTES</p><h3>Simple shapes, steady counting, and small wins.</h3><ul><li>We keep songs in C on standard ukulele and G on baritone, then add another easy chord only when a song needs it.</li><li>Success can be four steady strums while counting <strong>1 · 2 · 3 · 4</strong> and tapping a foot. Timing is the hardest part to learn; the mechanical chord shapes come with time.</li><li>Practice fret numbers, finger numbers, comfortable posture, and position. A string that does not press cleanly yet is growth—not failure.</li></ul></div></aside>`;
 if(type==='uke-general')return `<aside class="strum-callout"><div class="callout-mark">↓</div><div><p>OBJECTIVE NOTES</p><h3>Build useful chord families and steady timing.</h3><ul><li>Ukulele shapes are generally quick to add, so this path focuses on useful key families and the timing needed to play them in songs.</li><li>Build each shape with the same lead finger every time. New chords can be learned as a song calls for them.</li><li>Strum down with a relaxed index finger. Count <strong>1 · 2 · 3 · 4</strong> and let the strum and tapping foot move together.</li>${objectiveOneReturn()}</ul></div></aside>`;
 if(type==='strumming')return `<aside class="strum-callout"><div class="callout-mark">↕</div><div><p>STRUMMING NOTES</p><h3>See, hear, and feel each pattern.</h3><ul><li>Open Core 4/4, 3/4, or Sixteenth-Note Patterns, then choose an exercise. Select a chord for each measure and tap its name to see the shape.</li><li>Follow Along loops both measures continuously at your chosen tempo. Use Drums when you want a stronger beat underneath the guitar.</li><li><strong>Time signatures:</strong> 4/4 has four beats per measure; 3/4 has three and often feels like “ONE-two-three.” Eighth notes split each beat into two parts, and sixteenth notes split it into four.</li><li>A dot means your strumming hand keeps moving without touching the strings. Keep counting through the space.</li><li>In the sixteenth-note exercises, each group of four arrows fits inside one foot tap; the large number cycles through beats 1–4.</li></ul></div></aside>`;
 return `<aside class="strum-callout compact-callout"><div class="callout-mark">↕</div><div><p>HOW THESE PATTERNS WORK</p><h3>Choose a starting point or build your own.</h3><ul><li><strong>Common Progression Patterns</strong> provides ready-made four-chord loops. <strong>Custom Patterns</strong> lets you build a two- or four-chord exercise. <strong>Requested Patterns</strong> contains longer song sections requested by students.</li><li>Open a section, then select a numbered exercise. Read each exercise left to right and continue on the next row when its measures wrap.</li><li>Tap the beat grid in a measure to start Follow Along there. It repeats from that measure to the end; tap a chord name to see its shape.</li><li>Choose the strumming pattern and tempo that fit your goal. Four steady down-strums are always a good fallback while a chord change is still new.</li></ul></div></aside>`;
}
